(function () {const arrow ='<span aria-hidden="true">→</span>';const UI ={ResponsiveImage({src,alt ='',width,height,loading ='lazy',priority =false,sizes ='100vw',srcset =''} ={}) {return `<img src="${src}"${srcset ? `srcset="${srcset}"sizes="${sizes}"` : ''} alt="${alt}" width="${width}" height="${height}"${loading ? `loading="${loading}"` : ''}${priority ? ' fetchpriority="high"' : ''}>`;},Header() {return `<a class="brand logo-brand" href="#home" aria-label="Darcy Construction home">${UI.ResponsiveImage({src:'assets/variants/darcy-logo-768.webp',srcset:'assets/variants/darcy-logo-384.webp 384w, assets/variants/darcy-logo-768.webp 768w',sizes:'154px',alt:'Darcy Construction',width:768,height:511,loading:'eager'})}</a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="nav" aria-label="Open navigation"><span aria-hidden="true"></span><span aria-hidden="true"></span><span aria-hidden="true"></span></button><nav id="nav" aria-label="Main navigation"><a href="#story">Our story</a><a href="#approach">Our approach</a><a href="#services">What we do</a><a href="#sectors">Who we work for</a><a href="#work">Our work</a><a class="mobile-nav-cta" href="#contact">Start a conversation <span aria-hidden="true">↗</span></a></nav><a class="button button-small header-cta" href="#contact">Start a conversation</a>`;},Hero({variant ='home',eyebrow,title,body,image,imageAlt ='',primary,secondary,note } ={}) {if (variant ==='internal') {return `<section class="page-hero internal-hero" aria-labelledby="page-title"><span class="eyebrow">${eyebrow}</span><h1 id="page-title">${title}</h1><p>${body}</p></section>`;} return `<section class="hero" aria-labelledby="hero-title"><div class="hero-media">${UI.ResponsiveImage({src:image,alt:imageAlt,width:2000,height:1333,loading:'eager',priority:true})}</div><div class="hero-shade" aria-hidden="true"></div><div class="hero-inner"><div class="hero-copy"><span class="eyebrow">${eyebrow}</span><h1 id="hero-title">${title}</h1><p>${body}</p><div class="hero-actions"><a class="button" href="${primary.href}">${primary.label} <span aria-hidden="true">↗</span></a><a class="hero-text-link" href="${secondary.href}">${secondary.label} ${arrow}</a></div></div>${note ? `<div class="hero-note"><span>${note.label}</span><strong>${note.value}</strong><span>${note.detail}</span></div>` : ''}</div></section>`;},SectionHeader({eyebrow,title,body,id,className =''}) {return `<div class="section-intro ${className}"><span class="eyebrow">${eyebrow}</span><div><h2${id ? `id="${id}"` : ''}>${title}</h2>${body ? `<p>${body}</p>` : ''}</div></div>`;},TrustBar(items) {return `<section class="trustbar" aria-label="Darcy at a glance">${items.map(item => `<div><span class="trust-number">${item.value}</span><span>${item.label}</span></div>`).join('')}</section>`;},ServiceCard(item) {return `<article class="outcome-card"><span class="outcome-number">${item.number}</span><div><h3>${item.title}</h3><p>${item.body}</p><span class="outcome-services">${item.services}</span></div><a href="#services" aria-label="Explore services for: ${item.title}"><span aria-hidden="true">↗</span></a></article>`;},ProjectCard(project) {const href =project.href ||'#work';return `<article class="featured-project"><a class="featured-project-image" href="${href}" aria-label="Read the ${project.title} case study">${UI.ResponsiveImage({src:project.image,alt:`${project.title} completed by Darcy Construction`,width:550,height:450,loading:'lazy'})}<span>Read the story <i aria-hidden="true">↗</i></span></a><div class="featured-project-copy"><h3><a href="${href}">${project.title}</a></h3><p>${project.story}</p></div></article>`;},CaseStudyHero(project) {return `<section class="case-hero" aria-labelledby="case-title"><div class="case-hero-media">${UI.ResponsiveImage({src:project.image,alt:project.imageAlt,width:1600,height:1066,loading:'eager',priority:true})}</div><div class="case-hero-shade" aria-hidden="true"></div><div class="case-hero-copy"><span class="eyebrow">${project.sector} · ${project.location}</span><h1 id="case-title">${project.title}</h1><p>${project.intro}</p></div></section>`;},FactList(facts) {return `<dl class="fact-list">${facts.map(fact => `<div><dt>${fact.label}</dt><dd>${fact.value}</dd></div>`).join('')}</dl>`;},TestimonialCard(testimonial) {return `<figure><blockquote>${testimonial.quote}</blockquote><figcaption><strong>${testimonial.name}</strong><span>${testimonial.project}</span></figcaption></figure>`;},ProcessTimeline(steps) {return `<ol class="steps">${steps.map(step => `<li class="step"><b>${step.number}</b><h3>${step.title}</h3><p>${step.body}</p></li>`).join('')}</ol>`;},CTAPanel({title,body,href ='#contact',label ='Start a conversation',variant ='statement'}) {if (variant ==='footer') return `<div class="footer-lead"><span class="eyebrow">The Darcy Standard</span><h2>${title}</h2><a class="button button-light" href="${href}">${label} <span aria-hidden="true">↗</span></a></div>`;if (variant ==='relationship') return `<section class="statement internal-cta"><div><span class="eyebrow">Start a conversation</span><h2>${title}</h2></div><div><p>${body}</p><a class="button button-light" href="${href}">${label} <span aria-hidden="true">↗</span></a></div></section>`;return `<section class="statement"><h2>${title}</h2><p>${body}</p></section>`;},Footer() {return `${UI.CTAPanel({ variant: 'footer', title: 'Good buildings begin<br>with a good conversation.', label: 'Start a conversation' })}<div class="footer-grid"><div><div class="brand brand-light logo-brand footer-logo-brand">${UI.ResponsiveImage({src:'assets/variants/darcy-logo-768.webp',srcset:'assets/variants/darcy-logo-384.webp 384w, assets/variants/darcy-logo-768.webp 768w',sizes:'154px',alt:'Darcy Construction',width:768,height:511,loading:'lazy'})}</div><p>Trusted construction partners.<br>Romsey, Hampshire. Established 1999.</p></div><div><b>Explore</b><a href="#approach">Our approach</a><a href="#work">Our work</a><a href="#insights">Insights</a><a href="#careers">Join the team</a></div><div><b>Talk to us</b><a href="tel:01794519545">01794 519545</a><a href="mailto:enquiries@darcyconstruction.co.uk">enquiries@darcyconstruction.co.uk</a><p>Romsey, Hampshire</p></div></div><div class="footer-base"><span>© 2026 Darcy Construction</span><span>Privacy · Cookies · Legal</span></div>`;} };window.DarcyUI =Object.freeze(UI);})();